#!/usr/bin/env bash
# quest-worktree — one isolated tree per quest developer, ready to run quest-eval.
#
#   tools/quest-worktree.sh <quest-id>          # create (or repair) ~/rs-sdk-quests/<id>
#
# WHY
# Quest writers must not share a working tree: a shared tree makes every commit a
# race and sweeps someone else's half-tested script into the candidate. A plain
# `git worktree add` is not enough either, because three things the eval harness
# needs are NOT in git and are NOT regenerated by `bun install`:
#
#   node_modules                   (root, server/engine, server/webclient)
#   server/engine/data/pack        the map/obj/npc cache the fixture materializer reads
#   server/engine/data/players     where fixtures write .sav files
#   server/engine/data/market.sqlite*  the GE checkpoint authority the loader prefers
#
# Missing any of those fails as a *harness* error (exit 2), which reads like a
# broken quest script. So this script links them from the source checkout instead
# of leaving the next agent to discover it one failed attempt at a time.
#
# The links point back at the source tree, so a fixture account staged here is
# visible to the ONE local engine that is already running — that is intended:
# there is one world, and parallelism comes from disjoint accounts.
set -euo pipefail

SOURCE="${QUEST_LAB_SOURCE:-$HOME/rs-sdk-offline}"
ROOT="${QUEST_LAB_TREES:-$HOME/rs-sdk-quests}"
QUEST="${1:-}"
if [ -z "$QUEST" ]; then
    echo "usage: tools/quest-worktree.sh <quest-id>" >&2
    exit 2
fi

TREE="$ROOT/$QUEST"
BRANCH="quest/$QUEST"

if [ -d "$TREE" ]; then
    echo "reusing $TREE"
else
    mkdir -p "$ROOT"
    if git -C "$SOURCE" rev-parse --verify --quiet "refs/heads/$BRANCH" >/dev/null; then
        git -C "$SOURCE" worktree add "$TREE" "$BRANCH" >/dev/null
    else
        git -C "$SOURCE" worktree add "$TREE" -b "$BRANCH" >/dev/null
    fi
    echo "created $TREE on $BRANCH"
fi

link() { # link <relpath>
    local rel="$1" src="$SOURCE/$1" dst="$TREE/$1"
    if [ -e "$dst" ] && [ ! -L "$dst" ]; then
        echo "  keep  $rel (real directory already present)"
        return 0
    fi
    [ -e "$dst" ] && return 0
    mkdir -p "$(dirname "$dst")"
    ln -s "$src" "$dst"
    echo "  link  $rel -> $src"
}

link node_modules
link server/engine/node_modules
link server/webclient/node_modules
link server/engine/data/pack
link server/engine/data/players
for f in market.sqlite market.sqlite-shm market.sqlite-wal; do
    [ -e "$SOURCE/server/engine/data/$f" ] && link "server/engine/data/$f"
done

cat <<EOF

tree:   $TREE
next:
  cd $TREE
  bun build --target=bun bots/quests/<script>.ts --outdir /tmp/preflight-$QUEST
  bun quest-eval/run.ts --suite quest-eval/suites/$QUEST.json --runs 3
EOF
